<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/pagination.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';
try{$uid=(int)requireAuth()->id;$c=db();requirePermission($c,$uid,'suppliers.view');[$page,$size,$offset]=paginationInput($_GET);$search=trim((string)($_GET['search']??''));$type=trim((string)($_GET['type']??''));$where=['user_id=?'];$types='i';$args=[$uid];if($search!==''){$where[]="CONCAT_WS(' ',reference,name,email,phone,fiscal_id) LIKE ?";$types.='s';$args[]='%'.$search.'%';}if($type!==''){$where[]='type=?';$types.='s';$args[]=$type;}$w=implode(' AND ',$where);$s=$c->prepare("SELECT COUNT(*) total FROM suppliers WHERE $w");$s->bind_param($types,...$args);$s->execute();$total=(int)$s->get_result()->fetch_assoc()['total'];$s->close();$order=paginationSort($_GET,['name'=>'name','created'=>'id'],'created');$s=$c->prepare("SELECT id,reference,type,name,email,phone,address,fiscal_id FROM suppliers WHERE $w ORDER BY $order LIMIT ? OFFSET ?");$qt=$types.'ii';$qa=[...$args,$size,$offset];$s->bind_param($qt,...$qa);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();paginatedResponse($rows,$page,$size,$total);}catch(Throwable $e){jsonResponse(['success'=>false,'message'=>'Could not load suppliers.','error_code'=>'SUPPLIER_LIST_FAILED'],500);}
